   * Throws on the first failing stage; returns a summary when everything passes.
   */
  @func()
  async all(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Promise<string> {
    await this.lint(source);
    await this.typecheck(source);
    await this.test(source);
