+  test("ordered subsequences match common abbreviations", () => {
+    expect(fuzzyCommandScore(getEditorCommand("insert.mermaid")!, "mmd")).not.toBeNull();
+  });
+
+  test("unrelated queries are excluded", () => {
+    expect(fuzzyCommandScore(getEditorCommand("insert.table")!, "zebra")).toBeNull();
